/bin/bash -lc "python3 - <<'PY'
import json, urllib.request
for id in ['ieu-a-1069','ieu-a-1070','ieu-a-1071','ieu-a-1072','ukb-b-16881']:
    for url in [f'https://api.opengwas.io/api/gwasinfo/{id}', f'https://gwas-api.mrcieu.ac.uk/gwasinfo/{id}']:
        try:
            req=urllib.request.Request(url,headers={'Accept':'application/json'})
            data=urllib.request.urlopen(req,timeout=20).read().decode()[:2000]
            print('\\n',id,url,'\\n',data[:1200])
            break
        except Exception as e:
            last=e
    else:
        print(id,'ERR',last)
PY"
